import{_ as a,C as r,o as h,c as i,a3 as e,E as o}from"./chunks/framework.Ba39LDvt.js";const p=JSON.parse('{"title":"器件与工艺自学","description":"从胡正明器件教材、Pierret 与 Sze 出发，连接半导体物理、工艺步骤和器件仿真。","frontmatter":{"title":"器件与工艺自学","description":"从胡正明器件教材、Pierret 与 Sze 出发，连接半导体物理、工艺步骤和器件仿真。"},"headers":[],"relativePath":"self-learning/device.md","filePath":"self-learning/device.md","lastUpdated":1795513256000}'),n={name:"self-learning/device.md"};function l(s,t,c,b,u,_){const d=r("CourseTable");return h(),i("div",null,[t[0]||(t[0]=e('<h1 id="器件与工艺自学" tabindex="-1">器件与工艺自学 <a class="header-anchor" href="#器件与工艺自学" aria-label="Permalink to &quot;器件与工艺自学&quot;">​</a></h1><p>器件学习要把三件事接起来：<strong>材料里载流子如何运动、器件结构怎样控制电流、工艺如何把结构做出来</strong>。先掌握 PN 结、MOS 电容和 MOSFET，再按研究方向深入量子、光电、功率或新型器件。与 <a href="/shanghaitech-ic-wiki-dev.github.io/map/device">器件学习地图</a> 配合，不必在一开始就追逐所有前沿材料。</p><h2 id="入门-能带、结和-mos" tabindex="-1">入门：能带、结和 MOS <a class="header-anchor" href="#入门-能带、结和-mos" aria-label="Permalink to &quot;入门：能带、结和 MOS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>胡正明《Modern Semiconductor Devices for Integrated Circuits》</td><td>教材</td><td>入门—进阶</td><td>连接物理直觉、器件方程与集成电路应用；<a href="https://www.chu.berkeley.edu/" target="_blank" rel="noreferrer">作者主页</a> 提供书籍与讲义入口</td></tr><tr><td>Robert F. Pierret《Semiconductor Device Fundamentals》</td><td>教材</td><td>入门—进阶</td><td>适合补载流子统计、输运、PN 结及 MOS 器件的推导</td></tr><tr><td>基础固体物理与量子概念</td><td>先修知识</td><td>入门—进阶</td><td>先理解能带、费米能级、态密度与占据概率，再按需要补更深入内容</td></tr><tr><td><a href="https://nanohub.org/" target="_blank" rel="noreferrer">nanoHUB</a></td><td>教学与在线仿真平台</td><td>入门—进阶</td><td>可查找器件课程与交互工具；部分服务需要注册，使用范围以平台说明为准</td></tr></tbody></table><p>学习每个器件都画能带图和电势示意图，再分析平衡与偏置后的变化。分清漂移与扩散、电荷与电流、耗尽近似与完整求解的边界。遇到公式先检查单位和符号约定；不要把电子流向、电流方向与坐标正方向混为一谈。</p><h2 id="进阶-从理想模型到真实器件与工艺" tabindex="-1">进阶：从理想模型到真实器件与工艺 <a class="header-anchor" href="#进阶-从理想模型到真实器件与工艺" aria-label="Permalink to &quot;进阶：从理想模型到真实器件与工艺&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>Sze、Ng《Physics of Semiconductor Devices》</td><td>参考教材</td><td>进阶—深入</td><td>按专题查阅器件机制与非理想效应，不建议初学者一开始逐页通读</td></tr><tr><td>Plummer、Deal、Griffin《Silicon VLSI Technology》</td><td>工艺教材</td><td>进阶</td><td>理解氧化、扩散、离子注入、光刻、刻蚀和薄膜沉积怎样组成流程</td></tr><tr><td><a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT OpenCourseWare</a> 的微电子器件与制造课程</td><td>公开课入口</td><td>进阶</td><td>按器件物理或制造目标选课，不同时铺开所有专题</td></tr><tr><td><a href="https://bsim.berkeley.edu/" target="_blank" rel="noreferrer">BSIM</a></td><td>紧凑模型资源</td><td>进阶—深入</td><td>理解电路仿真模型如何抽象器件，区分模型参数与可直接测量的物理量</td></tr><tr><td>开源 PDK 文档</td><td>工艺与设计规则</td><td>进阶</td><td>从层定义、器件种类、设计规则与模型角理解工艺约束，入口见 <a href="/shanghaitech-ic-wiki-dev.github.io/eda/open-source">开源工具链</a></td></tr></tbody></table><p>必须区分三种对象：工艺仿真描述制造步骤如何形成结构；器件仿真求解结构中的电势与输运；SPICE 紧凑模型用于高效计算电路行为。它们不是可以互换的软件选项。技术计算机辅助设计（Technology Computer-Aided Design，TCAD）的结果也会依赖网格、材料参数、接触条件与所选物理模型。</p><p>工艺入门可沿“衬底 → 有源区与隔离 → 栅 → 源漏 → 接触与互连”理解典型 CMOS 流程，但实际顺序和细节随工艺变化。工艺节点名称不能直接当作所有几何尺寸，也不能单凭节点数字判断电路性能。</p><h2 id="实践-一次只研究一种机制" tabindex="-1">实践：一次只研究一种机制 <a class="header-anchor" href="#实践-一次只研究一种机制" aria-label="Permalink to &quot;实践：一次只研究一种机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>PN 结一维计算</td><td>Python 数值练习</td><td>入门</td><td>扫描掺杂，比较内建电势与耗尽宽度，检查适用近似</td></tr><tr><td>nanoHUB 器件实验</td><td>交互仿真</td><td>入门—进阶</td><td>选择一个 MOS 或结器件工具，保存模型设置和曲线，而非只截图</td></tr><tr><td>MOSFET 特性分析</td><td>SPICE 或器件仿真</td><td>进阶</td><td>分析转移与输出曲线，讨论阈值提取、跨导及短沟道效应</td></tr><tr><td>简单器件版图阅读</td><td>PDK 文档实验</td><td>进阶</td><td>对照层图理解栅、扩散区、接触与隔离；遵守模型和规则文件授权</td></tr></tbody></table><p>可选项目：比较不同栅压下 MOSFET 的输出曲线。先说明温度、几何尺寸和模型，再固定其他参数扫描一个变量；提取指标时明确方法。若改变网格后结果明显变化，应先检查数值收敛，而不是立即解释成新物理。没有实际测试与校准时，应称为模型结果，不宣称制造或测量结论。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',13)),o(d,{codes:"EE120,EE220,EE224A,EE2211"}),t[1]||(t[1]=e('<p>用器件基础课建立 PN 结与 MOS 概念，再按课程和研究需要进入器件物理、微电子器件或微纳加工。实际实验准入、设备培训与工艺使用须按学院规定办理，不能凭自学材料自行操作平台设备。更多方向入口见 <a href="/shanghaitech-ic-wiki-dev.github.io/research/devices">器件研究</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/platforms">学校平台</a>。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">上科大信息学院 2026–2027 学年开课计划</a>。</li><li>胡正明作者主页、nanoHUB、BSIM 与 MIT OCW 官方入口见上表；教材通过合法渠道获取。</li></ul>',3))])}const m=a(n,[["render",l]]);export{p as __pageData,m as default};
